jw,jh=iw-2*lip,ih-2*lip
for i in range(1,4):
    y=-jw/2+jw*i/4; r=r.union(box(0,T/2,y-b/2,y+b/2,-jh/2,jh/2))
for j in range(1,3):
    z=-jh/2+jh*j/3; r=r.union(box(0,T/2,-jw/2,jw/2,z-b/2,z+b/2))
result=r.clean()

